void Solver::bump_var(int var, double coeff) {
    // Increment activity
    activity[var] += var_inc * coeff;

    // Check for overflow and rescale all activities if needed
    if (activity[var] > 1e100) {
        const double SCALE = 1e-100;
        // Scale activities using raw pointer for speed
        double* actPtr = &activity[1];
        for (int i = vars; i > 0; --i) {
            *actPtr++ *= SCALE;
        }
        var_inc *= SCALE; // keep relative increments consistent
    }

    // Update VSIDS heap if the variable is present
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

